// WidgetResponseBody is used to define fields on response body types.
type WidgetResponseBody struct {
	ID             string `form:"id" json:"id" xml:"id"`
	ProjectID      string `form:"project_id" json:"project_id" xml:"project_id"`
	OrganizationID string `form:"organization_id" json:"organization_id" xml:"organization_id"`
	// Who saved it, when known
	CreatedByUserID *string `form:"created_by_user_id,omitempty" json:"created_by_user_id,omitempty" xml:"created_by_user_id,omitempty"`
	// Display name. Not unique: two people saving the same name is normal.
	Name string `form:"name" json:"name" xml:"name"`
	// What the widget is for, when its creator said
	Description *string `form:"description,omitempty" json:"description,omitempty" xml:"description,omitempty"`
	// The catalog dataset the widget asks
	Dataset string `form:"dataset" json:"dataset" xml:"dataset"`
	// The question: window, grain, dimensions, measures, filters, order and limit.
	// Planned against the catalog on save and on read.
	Query map[string]any `form:"query" json:"query" xml:"query"`
	// How the question is drawn: a chart type and its options. The client owns the
	// chart vocabulary; the server checks only that the chart can draw the
	// question.
	Visualization map[string]any `form:"visualization" json:"visualization" xml:"visualization"`
	// Present when the widget no longer works, naming what is wrong: a field the
	// catalog dropped, or a chart that cannot draw the question. A catalog change
	// fails visibly rather than returning wrong numbers.
	InvalidReason *string `form:"invalid_reason,omitempty" json:"invalid_reason,omitempty" xml:"invalid_reason,omitempty"`
	// The dashboards this widget is placed on, each once. Widgets are linked, not
	// copied: an edit reaches all of them, and a delete removes it from all of
	// them.
	Dashboards []*WidgetDashboardResponseBody `form:"dashboards" json:"dashboards" xml:"dashboards"`
	CreatedAt  string                         `form:"created_at" json:"created_at" xml:"created_at"`
	UpdatedAt  string                         `form:"updated_at" json:"updated_at" xml:"updated_at"`
}

