// ValidateCreateWidgetRequestBody runs the validations defined on
// CreateWidgetRequestBody
func ValidateCreateWidgetRequestBody(body *CreateWidgetRequestBody) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Dataset == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("dataset", "body"))
	}
	if body.Query == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("query", "body"))
	}
	if body.Visualization == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("visualization", "body"))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 200, false))
		}
	}
	if body.Description != nil {
		if utf8.RuneCountInString(*body.Description) > 2000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.description", *body.Description, utf8.RuneCountInString(*body.Description), 2000, false))
		}
	}
	if body.Dataset != nil {
		if utf8.RuneCountInString(*body.Dataset) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.dataset", *body.Dataset, utf8.RuneCountInString(*body.Dataset), 1, true))
		}
	}
	return
}

